{"security_risk":"LOW","summary":"Create audit logger","command":"create","path":"/workspace/backend/internal/audit/audit.go","file_text":"package audit

import (
	"context"
	"encoding/json"
	"log"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5/pgxpool"
)

type Logger struct {
	pool *pgxpool.Pool
}

func NewLogger(pool *pgxpool.Pool) *Logger { return &Logger{pool: pool} }

type Entry struct {
	ActorID    *uuid.UUID
	Role       string
	Action     string
	EntityType string
	EntityID   string
	Success    bool
	OccurredAt time.Time
	Details    map[string]interface{}
}

func (l *Logger) Write(ctx context.Context, e Entry) {
	if e.OccurredAt.IsZero() {
		e.OccurredAt = time.Now().UTC()
	}
	details := e.Details
	if details == nil {
		details = map[string]interface{}{}
	}
	payload, err := json.Marshal(details)
	if err != nil {
		log.Printf("audit marshal: %v", err)
		return
	}
	_, err = l.pool.Exec(ctx, `
		INSERT INTO audit_trail
		    (actor_id, role, action, entity_type, entity_id, success, occurred_at, details)
		VALUES ($1, NULLIF($2,''), $3, $4, NULLIF($5,''), $6, $7, $8::jsonb)
	`, e.ActorID, e.Role, e.Action, e.EntityType, e.EntityID, e.Success, e.OccurredAt, string(payload))
	if err != nil {
		log.Printf("audit write: %v", err)
	}
}"}

{"security_risk":"LOW","summary":"Create realtime hub and sink","command":"create","path":"/workspace/backend/internal/realtime/hub.go","file_text":"package realtime

import (
	"context"
	"encoding/json"
	"log"
	"sync"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5/pgxpool"
)

type Event struct {
	ID         int64                  `json:"id"`
	Type       string                 `json:"type"`
	EntityType string                 `json:"entityType"`
	EntityID   string                 `json:"entityId"`
	Payload    map[string]interface{} `json:"payload"`
	CreatedAt  time.Time              `json:"createdAt"`
}

// Hub publishes events to all connected WebSocket clients.
type Hub struct {
	mu          sync.RWMutex
	subscribers map[int64]chan Event
	nextID      int64
	pool        *pgxpool.Pool
}

func NewHub() *Hub {
	return &Hub{subscribers: map[int64]chan Event{}}
}

// AttachPool wires the hub into Postgres so event streams are persisted.
func (h *Hub) AttachPool(p *pgxpool.Pool) { h.pool = p }

// Subscribe returns an event channel and a unique subscriber id used for Unsubscribe.
func (h *Hub) Subscribe(buf int) (int64, <-chan Event) {
	ch := make(chan Event, buf)
	h.mu.Lock()
	h.nextID++
	id := h.nextID
	h.subscribers[id] = ch
	h.mu.Unlock()
	return id, ch
}

func (h *Hub) Unsubscribe(id int64) {
	h.mu.Lock()
	ch, ok := h.subscribers[id]
	if ok {
		delete(h.subscribers, id)
	}
	h.mu.Unlock()
	if ok {
		close(ch)
	}
}

func (h *Hub) Publish(ctx context.Context, e Event) {
	if h.pool != nil {
		row := h.pool.QueryRow(ctx, `
			INSERT INTO realtime_events (event_type, entity_type, entity_id, payload)
			VALUES ($1, $2, $3, $4::jsonb) RETURNING id, created_at
		`, e.Type, e.EntityType, e.EntityID, mustJSON(e.Payload))
		if err := row.Scan(&e.ID, &e.CreatedAt); err != nil {
			log.Printf("realtime insert: %v", err)
		}
	}
	h.mu.RLock()
	defer h.mu.RUnlock()
	for _, sub := range h.subscribers {
		select {
		case sub <- e:
		default:
			// drop on slow consumer
		}
	}
}

func mustJSON(v map[string]interface{}) string {
	if v == nil {
		v = map[string]interface{}{}
	}
	b, _ := json.Marshal(v)
	return string(b)
}

type Sink struct {
	hub *Hub
}

func NewSink(h *Hub) *Sink { return &Sink{hub: h} }

func (s *Sink) Emit(ctx context.Context, eventType, entityType, entityID string, payload map[string]interface{}) {
	if s == nil || s.hub == nil {
		return
	}
	s.hub.Publish(ctx, Event{
		Type:       eventType,
		EntityType: entityType,
		EntityID:   entityID,
		Payload:    payload,
		CreatedAt:  time.Now().UTC(),
	})
}

// NewEventID returns a unique id (uuid) helper for payloads.
func NewEventID() string { return uuid.NewString() }"}

{"security_risk":"LOW","summary":"Create auth middleware","command":"create","path":"/workspace/backend/internal/auth/auth.go","file_text":"package auth

import (
	"context"
	"errors"
	"strings"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"golang.org/x/crypto/bcrypt"
)

type Session struct {
	UserID     uuid.UUID
	ActiveRole string
	Roles      []string
	ExpiresAt  time.Time
}

type Store struct {
	pg *pgxpool.Pool
}

func NewStore(pg *pgxpool.Pool) *Store { return &Store{pg: pg} }

// Authenticate verifies username/password against bcrypt hash.
func (s *Store) Authenticate(ctx context.Context, username, password string) (*Session, error) {
	var (
		userID    uuid.UUID
		hash      string
		roles     []string
		active    bool
	)
	row := s.pg.QueryRow(ctx, `SELECT user_id, password_hash, roles, active FROM users WHERE username = $1`, username)
	if err := row.Scan(&userID, &hash, &roles, &active); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, ErrInvalidCredentials
		}
		return nil, err
	}
	if !active {
		return nil, ErrInvalidCredentials
	}
	if err := bcrypt.CompareHashAndPassword([]byte(hash), []byte(password)); err != nil {
		return nil, ErrInvalidCredentials
	}
	activeRole := ""
	if len(roles) > 0 {
		activeRole = roles[0]
	}
	return &Session{UserID: userID, ActiveRole: activeRole, Roles: roles}, nil
}

// Issue creates a new session token (random string) and persists it.
func (s *Store) Issue(ctx context.Context, sess *Session, ttl time.Duration) (string, error) {
	token, err := newToken()
	if err != nil {
		return "", err
	}
	expires := time.Now().UTC().Add(ttl)
	_, err = s.pg.Exec(ctx, `
		INSERT INTO session_tokens (token, user_id, active_role, expires_at)
		VALUES ($1, $2, $3, $4)
	`, token, sess.UserID, sess.ActiveRole, expires)
	if err != nil {
		return "", err
	}
	return token, nil
}

// Lookup resolves a bearer [REDACTED] to a session.
func (s *Store) Lookup(ctx context.Context, token string) (*Session, error) {
	if token == "" {
		return nil, ErrUnauthorized
	}
	var (
		userID    uuid.UUID
		activeRole string
		expiresAt time.Time
		roles     []string
		active    bool
	)
	row := s.pg.QueryRow(ctx, `
		SELECT st.user_id, st.active_role, st.expires_at, u.roles, u.active
		FROM session_tokens st JOIN users u ON st.user_id = u.user_id
		WHERE st.token = $1
	`, token)
	if err := row.Scan(&userID, &activeRole, &expiresAt, &roles, &active); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, ErrUnauthorized
		}
		return nil, err
	}
	if !active || time.Now().UTC().After(expiresAt) {
		return nil, ErrUnauthorized
	}
	return &Session{UserID: userID, ActiveRole: activeRole, Roles: roles, ExpiresAt: expiresAt}, nil
}

func (s *Store) SetActiveRole(ctx context.Context, token, role string) error {
	_, err := s.pg.Exec(ctx, `UPDATE session_tokens SET active_role = $1 WHERE token = $2`, role, token)
	return err
}

func (s *Store) Revoke(ctx context.Context, token string) error {
	_, err := s.pg.Exec(ctx, `DELETE FROM session_tokens WHERE token = $1`, token)
	return err
}

func (s *Store) Cleanup(ctx context.Context) {
	_, _ = s.pg.Exec(ctx, `DELETE FROM session_tokens WHERE expires_at < NOW()`)
}

// HashPassword bcrypts the supplied password.
func HashPassword(pw string) (string, error) {
	h, err := bcrypt.GenerateFromPassword([]byte(pw), bcrypt.DefaultCost)
	return string(h), err
}

var (
	ErrInvalidCredentials = errors.New("invalid_credentials")
	ErrUnauthorized       = errors.New("unauthorized")
	ErrRoleNotHeld        = errors.New("role_not_held")
)

func newToken() (string, error) {
	u, err := uuid.NewRandom()
	if err != nil {
		return "", err
	}
	return strings.ReplaceAll(u.String(), "-", ""), nil
}"}

{"security_risk":"LOW","summary":"Create middleware","command":"create","path":"/workspace/backend/internal/api/middleware.go","file_text":"package api

import (
	"errors"
	"log"
	"net/http"
	"strings"
	"time"

	"github.com/gin-gonic/gin"

	"labdeliver/backend/internal/auth"
)

const sessionKey = "session"

func requestLogger() gin.HandlerFunc {
	return func(c *gin.Context) {
		start := time.Now()
		c.Next()
		log.Printf("%-6s %-32s -> %d (%s) ua=%q", c.Request.Method, c.Request.URL.Path, c.Writer.Status(), time.Since(start), c.Request.UserAgent())
	}
}

// authRequired validates the bearer [REDACTED] and stores the session in the context.
func authRequired(s *State) gin.HandlerFunc {
	return func(c *gin.Context) {
		token := bearerToken(c.Request.Header.Get("Authorization"))
		if token == "" {
			c.AbortWithStatusJSON(http.StatusUnauthorized, gin.H{"error": "unauthorized", "code": "unauthorized"})
			return
		}
		sess, err := s.Auth.Lookup(c.Request.Context(), token)
		if err != nil {
			if errors.Is(err, auth.ErrUnauthorized) {
				c.AbortWithStatusJSON(http.StatusUnauthorized, gin.H{"error": "unauthorized", "code": "unauthorized"})
				return
			}
			c.AbortWithStatusJSON(http.StatusInternalServerError, gin.H{"error": "auth lookup failed", "code": "internal_error"})
			return
		}
		if sess.ActiveRole == "" {
			c.AbortWithStatusJSON(http.StatusConflict, gin.H{"error": "role not selected", "code": "role_not_selected"})
			return
		}
		c.Set(sessionKey, sess)
		c.Set("token", token)
		c.Next()
	}
}

// requireRole enforces a specific active role.
func requireRole(s *State, role string) gin.HandlerFunc {
	return func(c *gin.Context) {
		sess, _ := c.Get(sessionKey)
		if sess == nil {
			c.AbortWithStatusJSON(http.StatusUnauthorized, gin.H{"error": "unauthorized", "code": "unauthorized"})
			return
		}
		cur := sess.(*auth.Session)
		if cur.ActiveRole != role {
			c.AbortWithStatusJSON(http.StatusForbidden, gin.H{"error": "forbidden", "code": "forbidden"})
			return
		}
		c.Next()
	}
}

// requireAnyRole enforces that the active role is one of the allowed list.
func requireAnyRole(s *State, roles ...string) gin.HandlerFunc {
	return func(c *gin.Context) {
		sess, _ := c.Get(sessionKey)
		if sess == nil {
			c.AbortWithStatusJSON(http.StatusUnauthorized, gin.H{"error": "unauthorized", "code": "unauthorized"})
			return
		}
		cur := sess.(*auth.Session)
		ok := false
		for _, r := range roles {
			if cur.ActiveRole == r {
				ok = true
				break
			}
		}
		if !ok {
			c.AbortWithStatusJSON(http.StatusForbidden, gin.H{"error": "forbidden", "code": "forbidden"})
			return
		}
		c.Next()
	}
}

func bearerToken(h string) string {
	const prefix = "Bearer "
	if strings.HasPrefix(h, prefix) {
		return strings.TrimSpace(h[len(prefix):])
	}
	return ""
}

func currentSession(c *gin.Context) *auth.Session {
	v, ok := c.Get(sessionKey)
	if !ok {
		return nil
	}
	return v.(*auth.Session)
}

func currentToken(c *gin.Context) string {
	if t, ok := c.Get("token"); ok {
		if s, ok := t.(string); ok {
			return s
		}
	}
	return ""
}"}

{"security_risk":"LOW","summary":"Create serviceability engine","command":"create","path":"/workspace/backend/internal/serviceability/engine.go","file_text":"package serviceability

import (
	"context"
	"encoding/json"
	"fmt"
	"math"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/redis/go-redis/v9"

	"labdeliver/backend/internal/audit"
	"labdeliver/backend/internal/realtime"
)

type Engine struct {
	pg     *pgxpool.Pool
	rds    *redis.Client
	audit  *audit.Logger
	sink   *realtime.Sink
}

func NewEngine(pg *pgxpool.Pool, rds *redis.Client, audit *audit.Logger, sink *realtime.Sink) *Engine {
	return &Engine{pg: pg, rds: rds, audit: audit, sink: sink}
}

// ReasonCode enumerates serviceability failure reasons.
type ReasonCode string

const (
	ReasonServiceable           ReasonCode = "serviceable"
	ReasonOutsideCoverage       ReasonCode = "outside_service_coverage"
	ReasonNoAcceptingLab        ReasonCode = "no_accepting_laboratory"
	ReasonNoRoute               ReasonCode = "no_route"
	ReasonInsufficientCapacity  ReasonCode = "insufficient_capacity"
	ReasonDeadlineUnreachable   ReasonCode = "deadline_unreachable"
	ReasonHandlingUnsatisfiable ReasonCode = "handling_rules_unsatisfiable"
)

type CheckInput struct {
	Origin              Coordinate    `json:"origin"`
	OriginType          string        `json:"originType"`
	OriginNodeID        *uuid.UUID    `json:"originNodeId,omitempty"`
	SampleTypeID        uuid.UUID     `json:"sampleTypeId"`
	RequestedAt         time.Time     `json:"requestedAt"`
	DeliveryDeadline    time.Time     `json:"deliveryDeadline"`
	EarliestCollection  *time.Time    `json:"earliestCollectionAt,omitempty"`
	LatestCollection    *time.Time    `json:"latestCollectionAt,omitempty"`
	ContainerType       string        `json:"containerType,omitempty"`
	TemperatureMinC     float64       `json:"temperatureMinC,omitempty"`
	TemperatureMaxC     float64       `json:"temperatureMaxC,omitempty"`
	Incompatibilities   []uuid.UUID   `json:"incompatibleSampleTypes,omitempty"`
}

type CheckResult struct {
	Serviceable          bool       `json:"serviceable"`
	Reason               ReasonCode `json:"reason"`
	TargetLaboratoryID   *uuid.UUID `json:"targetLaboratoryId,omitempty"`
	EstimatedArrivalAt   *time.Time `json:"estimatedArrivalAt,omitempty"`
	ServiceabilityVersion int       `json:"serviceabilityVersion"`
	PathSummary          []uuid.UUID `json:"pathSummary,omitempty"`
}

type Coordinate struct {
	Latitude  float64 `json:"latitude"`
	Longitude float64 `json:"longitude"`
}

type ServiceabilitySnapshot struct {
	Version                   int         `json:"version"`
	Status                    string      `json:"status"`
	ComputedAt                time.Time   `json:"computedAt"`
	NetworkRevision           int         `json:"networkRevision"`
	Regions                   []Region    `json:"regions"`
	ActiveCollectionPointCount int        `json:"activeCollectionPointCount"`
}

type Region struct {
	LocationID uuid.UUID `json:"locationId"`
	Name       string    `json:"name"`
	Latitude   float64   `json:"latitude"`
	Longitude  float64   `json:"longitude"`
	CoverageKm float64   `json:"coverageKm"`
}

// BumpRevision increments network_revision and refreshes the serviceability snapshot.
func (e *Engine) BumpRevision(ctx context.Context, actorID *uuid.UUID, role string) error {
	_, err := e.pg.Exec(ctx, `UPDATE network_revision SET revision = revision + 1, updated_at = NOW()`)
	if err != nil {
		return err
	}
	_, err = e.Recompute(ctx)
	if err != nil {
		return err
	}
	e.audit.Write(ctx, audit.Entry{
		ActorID: actorID, Role: role, Action: "network_revision_bumped",
		EntityType: "network", EntityID: "global", Success: true,
	})
	e.sink.Emit(ctx, "network_revision_bumped", "network", "global", map[string]interface{}{})
	return nil
}

func (e *Engine) Recompute(ctx context.Context) (int, error) {
	var rev int
	if err := e.pg.QueryRow(ctx, `SELECT revision FROM network_revision LIMIT 1`).Scan(&rev); err != nil {
		return 0, err
	}
	regions, err := e.collectRegions(ctx)
	if err != nil {
		return 0, err
	}
	var nextVersion int
	if err := e.pg.QueryRow(ctx, `
		INSERT INTO serviceability_versions
		    (version, status, computed_at, network_revision, regions, active_collection_point_count)
		VALUES (
		    COALESCE((SELECT MAX(version) FROM serviceability_versions),0)+1,
		    'complete', NOW(), $1, $2::jsonb, $3
		)
		RETURNING version
	`, rev, toJSON(regions), len(regions)).Scan(&nextVersion); err != nil {
		return 0, err
	}
	cacheKey := fmt.Sprintf("svc:current:%d", nextVersion)
	payload, _ := json.Marshal(ServiceabilitySnapshot{
		Version: nextVersion, Status: "complete", ComputedAt: time.Now().UTC(),
		NetworkRevision: rev, Regions: regions, ActiveCollectionPointCount: len(regions),
	})
	_ = e.rds.Set(ctx, cacheKey, string(payload), 10*time.Minute).Err()
	return nextVersion, nil
}

func (e *Engine) LatestVersion(ctx context.Context) (ServiceabilitySnapshot, error) {
	var snap ServiceabilitySnapshot
	var regionsJSON []byte
	row := e.pg.QueryRow(ctx, `
		SELECT version, status, computed_at, network_revision, regions, active_collection_point_count
		FROM serviceability_versions
		ORDER BY version DESC LIMIT 1
	`)
	if err := row.Scan(&snap.Version, &snap.Status, &snap.ComputedAt, &snap.NetworkRevision, &regionsJSON, &snap.ActiveCollectionPointCount); err != nil {
		return snap, err
	}
	if len(regionsJSON) > 0 {
		_ = json.Unmarshal(regionsJSON, &snap.Regions)
	}
	return snap, nil
}

func (e *Engine) collectRegions(ctx context.Context) ([]Region, error) {
	rows, err := e.pg.Query(ctx, `
		SELECT location_id, name, latitude, longitude, coverage_km
		FROM locations
		WHERE active = TRUE AND functions ? 'collection_point'
	`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []Region
	for rows.Next() {
		var r Region
		if err := rows.Scan(&r.LocationID, &r.Name, &r.Latitude, &r.Longitude, &r.CoverageKm); err != nil {
			return nil, err
		}
		out = append(out, r)
	}
	return out, rows.Err()
}

// Check performs the synchronous serviceability dry-run.
func (e *Engine) Check(ctx context.Context, in CheckInput) (CheckResult, error) {
	res := CheckResult{Serviceability: false, Reason: ReasonHandlingUnsatisfiable, ServiceabilityVersion: 1}
	snap, err := e.LatestVersion(ctx)
	if err != nil {
		return res, err
	}
	res.ServiceabilityVersion = snap.Version

	// 1. Origin within 5km of an active collection point (or origin is a node/clinic inside).
	covered := false
	if in.OriginType == "node" && in.OriginNodeID != nil {
		covered = true
	} else {
		for _, r := range snap.Regions {
			if haversineKm(in.Origin.Latitude, in.Origin.Longitude, r.Latitude, r.Longitude) <= r.CoverageKm {
				covered = true
				break
			}
		}
	}
	if !covered {
		res.Reason = ReasonOutsideCoverage
		return res, nil
	}

	// 2. Sample type metadata.
	var (
		stRequiresCooled bool
		stContainer      string
		stTempMin        float64
		stTempMax        float64
		stBatchAllowed   bool
	)
	row := e.pg.QueryRow(ctx, `
		SELECT requires_cooled_route, container_type, temperature_min_c, temperature_max_c, batching_allowed
		FROM sample_types WHERE sample_type_id = $1
	`, in.SampleTypeID)
	if err := row.Scan(&stRequiresCooled, &stContainer, &stTempMin, &stTempMax, &stBatchAllowed); err != nil {
		res.Reason = ReasonHandlingUnsatisfiable
		return res, nil
	}
	if stRequiresCooled {
		// Will require cooled route / lab capacity (checked during route search).
	}

	// 3. Find accepting laboratory.
	labRows, err := e.pg.Query(ctx, `
		SELECT la.laboratory_id, l.name, l.latitude, l.longitude
		FROM laboratory_acceptance la
		JOIN locations l ON l.location_id = la.laboratory_id
		WHERE la.sample_type_id = $1 AND la.accepts = TRUE AND l.active = TRUE
	`, in.SampleTypeID)
	if err != nil {
		return res, err
	}
	defer labRows.Close()
	type labOpt struct {
		id       uuid.UUID
		name     string
		lat, lon float64
	}
	var labs []labOpt
	for labRows.Next() {
		var lo labOpt
		if err := labRows.Scan(&lo.id, &lo.name, &lo.lat, &lo.lon); err != nil {
			return res, err
		}
		labs = append(labs, lo)
	}
	if len(labs) == 0 {
		res.Reason = ReasonNoAcceptingLab
		return res, nil
	}

	// 4. Find a valid route from each candidate collection point to each lab.
	collectionPoints := snap.Regions
	if in.OriginType == "node" && in.OriginNodeID != nil {
		// origin is a node - start at origin node.
		collectionPoints = nil
		var originNode Region
		if err := e.pg.QueryRow(ctx, `SELECT location_id, name, latitude, longitude, coverage_km FROM locations WHERE location_id = $1 AND active = TRUE`, in.OriginNodeID).
			Scan(&originNode.LocationID, &originNode.Name, &originNode.Latitude, &originNode.Longitude, &originNode.CoverageKm); err == nil {
			collectionPoints = []Region{originNode}
		}
	}

	bestETA := time.Time{}
	var bestPath []uuid.UUID
	var bestLab uuid.UUID
	routeFound := false
	for _, cp := range collectionPoints {
		for _, lab := range labs {
			path, travelMin, ok := shortestPath(ctx, e.pg, cp.LocationID, lab.id, stRequiresCooled)
			if !ok {
				continue
			}
			eta := in.RequestedAt.Add(time.Duration(travelMin) * time.Minute)
			if !eta.Before(in.DeliveryDeadline) {
				continue
			}
			if !routeFound || eta.Before(bestETA) {
				routeFound = true
				bestETA = eta
				bestPath = path
				bestLab = lab.id
			}
		}
	}
	if !routeFound {
		res.Reason = ReasonNoRoute
		return res, nil
	}

	// 5. Capacity check.
	if !capacityCheck(ctx, e.pg, bestPath, stRequiresCooled) {
		res.Reason = ReasonInsufficientCapacity
		return res, nil
	}

	res.Serviceable = true
	res.Reason = ReasonServiceable
	res.TargetLaboratoryID = &bestLab
	res.EstimatedArrivalAt = &bestETA
	res.PathSummary = bestPath
	return res, nil
}

func capacityCheck(ctx context.Context, pg *pgxpool.Pool, path []uuid.UUID, cooled bool) bool {
	if len(path) < 2 {
		return true
	}
	// Check node storage and connection capacity for path.
	for i := 0; i < len(path); i++ {
		id := path[i]
		if i > 0 {
			// Connection from path[i-1] -> path[i]
			var (
				capacity, reserved, cooledCap, cooledRes int
				isCooled bool
			)
			if err := pg.QueryRow(ctx, `SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units, cooled FROM connections WHERE from_location_id = $1 AND to_location_id = $2 AND active = TRUE`, path[i-1], id).
				Scan(&capacity, &reserved, &cooledCap, &cooledRes, &isCooled); err != nil {
				return false
			}
			if cooled {
				if !isCooled {
					return false
				}
				if cooledCap-cooledRes < 1 {
					return false
				}
			} else if capacity-reserved < 1 {
				return false
			}
		}
		if i < len(path)-1 {
			var capU, resU, cCap, cRes int
			if err := pg.QueryRow(ctx, `SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units FROM locations WHERE location_id = $1`, id).
				Scan(&capU, &resU, &cCap, &cRes); err != nil {
				return false
			}
			if cooled {
				if cCap-cRes < 1 {
					return false
				}
			} else if capU-resU < 1 {
				return false
			}
		}
	}
	return true
}

// shortestPath finds the shortest path (by travel minutes) between two locations
// that satisfies cooled constraints. Returns the path and total travel minutes.
func shortestPath(ctx context.Context, pg *pgxpool.Pool, from, to uuid.UUID, cooled bool) ([]uuid.UUID, int, bool) {
	// Dijkstra with priority queue stored in map for simplicity.
	type state struct {
		id    uuid.UUID
		cost  int
		prior uuid.UUID
	}
	dist := map[uuid.UUID]int{from: 0}
	prev := map[uuid.UUID]uuid.UUID{}
	pq := map[uuid.UUID]int{from: 0}
	for len(pq) > 0 {
		var cur uuid.UUID
		curCost := math.MaxInt32
		for id, c := range pq {
			if c < curCost {
				curCost = c
				cur = id
			}
		}
		delete(pq, cur)
		if cur == to {
			break
		}
		rows, err := pg.Query(ctx, `
			SELECT to_location_id, travel_minutes, cooled
			FROM connections
			WHERE from_location_id = $1 AND active = TRUE
		`, cur)
		if err != nil {
			return nil, 0, false
		}
		for rows.Next() {
			var next uuid.UUID
			var travel int
			var isCooled bool
			if err := rows.Scan(&next, &travel, &isCooled); err != nil {
				rows.Close()
				return nil, 0, false
			}
			if cooled && !isCooled {
				continue
			}
			nd := curCost + travel
			if existing, ok := dist[next]; !ok || nd < existing {
				dist[next] = nd
				prev[next] = cur
				pq[next] = nd
			}
		}
		rows.Close()
	}
	finalCost, ok := dist[to]
	if !ok {
		return nil, 0, false
	}
	// reconstruct path
	var path []uuid.UUID
	for cur := to; cur != uuid.Nil; cur = prev[cur] {
		path = append([]uuid.UUID{cur}, path...)
		if cur == from {
			break
		}
	}
	if len(path) == 0 || path[0] != from {
		return nil, 0, false
	}
	return path, finalCost, true
}

func toJSON(v interface{}) string {
	b, _ := json.Marshal(v)
	return string(b)
}

// haversineKm returns the great-circle distance between two coordinates in kilometres.
func haversineKm(lat1, lon1, lat2, lon2 float64) float64 {
	const R = 6371.0
	rad := math.Pi / 180
	dLat := (lat2 - lat1) * rad
	dLon := (lon2 - lon1) * rad
	a := math.Sin(dLat/2)*math.Sin(dLat/2) +
		math.Cos(lat1*rad)*math.Cos(lat2*rad)*math.Sin(dLon/2)*math.Sin(dLon/2)
	c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
	return R * c
}"}

{"security_risk":"LOW","summary":"Create admin bootstrap","command":"create","path":"/workspace/backend/internal/boot/admin.go","file_text":"package boot

import (
	"context"
	"errors"
	"fmt"
	"log"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	"labdeliver/backend/internal/auth"
	"labdeliver/backend/internal/config"
)

// EnsureAdmin creates the first administrator account when no users exist.
// Calling this when users already exist is a no-op.
func EnsureAdmin(ctx context.Context, pg *pgxpool.Pool, cfg config.Config) error {
	var count int
	if err := pg.QueryRow(ctx, `SELECT COUNT(*) FROM users`).Scan(&count); err != nil {
		return fmt.Errorf("count users: %w", err)
	}
	if count > 0 {
		return nil
	}
	hash, err := auth.HashPassword(cfg.AdminPassword)
	if err != nil {
		return fmt.Errorf("hash admin password: %w", err)
	}
	uid := uuid.New()
	_, err = pg.Exec(ctx, `
		INSERT INTO users (user_id, username, password_hash, email, full_name, phone, roles, qualifications, certifications, active, available, capacity_units)
		VALUES ($1, $2, $3, $4, $5, '', ARRAY['administrator']::TEXT[], '{}'::TEXT[], '[]'::jsonb, TRUE, TRUE, 100)
	`, uid, cfg.AdminUsername, hash, "", cfg.AdminUsername)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil
		}
		return fmt.Errorf("insert admin: %w", err)
	}
	log.Printf("created initial administrator username=%s", cfg.AdminUsername)
	return nil
}"}

