// handleAuthenticate processes /api/authenticate-user.
func handleAuthenticate(c *gin.Context) {
	var in struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	if in.Username == "" || in.Password == "" {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "username and password required"))
		return
	}
	ctx := c.Request.Context()
	sess, err := globalState.Auth.Authenticate(ctx, in.Username, in.Password)
	if err != nil {
		if errors.Is(err, auth.ErrInvalidCredentials) {
			WriteError(c, Err(http.StatusUnauthorized, "invalid_credentials", "invalid credentials"))
			return
		}
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", "authentication failed"))
		return
	}
	token, err := globalState.Auth.Issue(ctx, sess, 8*time.Hour)
	if err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", "session issue failed"))
		return
	}
	auditWrite(ctx, nil, "auth", "authenticate", "user", sess.UserID.String(), true, map[string]any{
		"username": in.Username,
	})
	c.JSON(http.StatusOK, gin.H{"data": gin.H{
		"sessionToken": token,
		"userId":       sess.UserID,
		"roles":        sess.Roles,
		"activeRole":   sess.ActiveRole,
	}})
}

// handleSelectActiveRole switches the active role for the current session.
func handleSelectActiveRole(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		Role string `json:"role"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	if in.Role == "" {
		WriteError(c, Err(http.StatusBadRequest, "invalid_role", "role required"))
		return
	}
	has := false
	for _, r := range sess.Roles {
		if r == in.Role {
			has = true
			break
		}
	}
	if !has {
		WriteError(c, Err(http.StatusForbidden, "role_not_held", "role not held by user"))
		return
	}
	if err := globalState.Auth.SetActiveRole(c.Request.Context(), currentToken(c), in.Role); err != nil {
		WriteError(c, Err(http.StatusInternalServerError, "internal_error", "could not switch role"))
		return
	}
	sess.ActiveRole = in.Role
	auditWrite(c.Request.Context(), &sess.UserID, in.Role, "select_active_role", "user", sess.UserID.String(), true, nil)
	c.JSON(http.StatusOK, gin.H{"data": gin.H{
		"activeRole": in.Role,
		"roles":      sess.Roles,
	}})
}

// handleSignOut revokes the bearer [REDACTED]
func handleSignOut(c *gin.Context) {
	sess := currentSession(c)
	token := currentToken(c)
	if err := globalState.Auth.Revoke(c.Request.Context(), token); err != nil {
