// handleCreateUser creates a user with the supplied roles + qualifications.
func handleCreateUser(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		Username           string             `json:"username"`
		InitialPassword    string             `json:"initialPassword"`
		Email              string             `json:"email"`
		FullName           string             `json:"fullName"`
		Phone              string             `json:"phone"`
		Roles              []string           `json:"roles"`
		Qualifications     []string           `json:"qualifications"`
		Certifications     []store.Cert       `json:"certifications"`
		Active             bool               `json:"active"`
		AssignedLocationID *string            `json:"assignedLocationId"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	if in.Username == "" || in.InitialPassword == "" || len(in.Roles) == 0 {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "username, initialPassword and roles are required"))
