// validateRoles checks the supplied roles against the allowed enum.
func validateRoles(roles []string) APIError {
	allowed := map[string]bool{
		"administrator": true, "dispatcher": true, "requester": true,
		"collection_professional": true, "delivery_partner": true,
		"node_handler": true, "laboratory_team": true,
	}
	for _, r := range roles {
		if !allowed[r] {
			return Err(http.StatusBadRequest, "invalid_role", "unknown role "+r)
		}
	}
	return APIError{}
}

func hasAnyRole(sess interface{}, roles ...string) bool {
	cs, ok := sess.(*auth.Session)
	if !ok {
		return false
	}
	for _, r := range roles {
		if cs.ActiveRole == r {
			return true
		}
	}
	return false
}

func nullUUID(id uuid.UUID) interface{} {
	if id == uuid.Nil {
		return nil
	}
	return id
}

// helper used elsewhere
var _ = time.RFC3339"}

