func defaultStr(s, def string) string {
	if s == "" {
		return def
	}
	return s
}

func orDefault(s, def string) string {
	if s == "" {
		return def
	}
	return s
}

func buildSampleState(ctx context.Context, id uuid.UUID, sess interface{}) (gin.H, APIError) {
	row := globalState.PG.QueryRow(ctx, `
		SELECT sample_id, request_id, requester_id, sample_type_id, origin_type, latitude, longitude,
		       requested_at, delivery_deadline, earliest_collection_at, latest_collection_at,
		       container_type, temperature_min_c, temperature_max_c, COALESCE(incompatible_sample_types,'{}'),
		       active_journey_id, current_holder_id, target_lab_id, status, sealed, location_recorded_at, location_latitude, location_longitude
		FROM samples WHERE sample_id=$1
	`, id)
	var s store.Sample
	var originType, status string
	var inc []string
	var activeJ, currentHolder, targetLab *uuid.UUID
	var latRecAt *time.Time
	var latRec, lonRec *float64
	if err := row.Scan(&s.SampleID, &s.RequestID, &s.RequesterID, &s.SampleTypeID, &originType, &s.Origin.Latitude, &s.Origin.Longitude,
		&s.RequestedAt, &s.DeliveryDeadline, &s.EarliestCollectionAt, &s.LatestCollectionAt,
		&s.ContainerType, &s.TemperatureMinC, &s.TemperatureMaxC, &inc,
		&activeJ, &currentHolder, &targetLab, &status, &s.Sealed, &latRecAt, &latRec, &lonRec); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, Err(http.StatusNotFound, "not_found", "sample not found")
		}
		return nil, Err(http.StatusInternalServerError, "internal_error", err.Error())
	}
	if sess != nil {
		role := ""
		if cs, ok := sess.(*authSessionShim); ok && cs != nil {
			role = cs.ActiveRole
		}
		if role != "administrator" && role != "dispatcher" && role != "requester" {
			return nil, Err(http.StatusForbidden, "role_not_held", "lifecycle is dispatcher-only")
		}
		if role == "requester" {
			// requester can only see their own
			if cs, ok := sess.(*authSessionShim); ok && cs != nil && cs.UserID != s.RequesterID {
				return nil, Err(http.StatusForbidden, "not_your_sample", "not your sample"))
			}
		}
	}
	// Build timeline
	var tl []map[string]any
	if globalState.Audit != nil {
		entries, _ := globalState.Audit.Search(ctx, map[string]any{"entityType": "sample", "entityId": id.String(), "limit": 500, "order": "newest_first"})
		for _, e := range entries {
			tl = append(tl, map[string]any{
				"eventId": e.EventID, "action": e.Action, "actorId": ptrString(e.ActorID), "role": e.Role,
				"entityType": e.EntityType, "entityId": e.EntityID, "success": e.Success,
