// reofferAssignment picks another qualified worker and re-offers.
func reofferAssignment(ctx interface{ Done() <-chan struct{} }, id uuid.UUID, a assignment) {
	// Try to find a different worker for the same role.
	var role string
	switch a.Kind {
	case "collection":
		role = "collection_professional"
	case "transport":
		role = "delivery_partner"
	case "node":
		role = "node_handler"
	case "laboratory":
		role = "laboratory_team"
	}
	if role == "" {
		return
	}
	rows, err := globalState.PG.Query(castCtx(ctx), `
		SELECT user_id FROM users
		WHERE active=TRUE AND available=TRUE AND $1 = ANY(roles)
		  AND (decline_count < 3)
		  AND user_id NOT IN (SELECT worker_id FROM assignments WHERE assignment_id=$2 AND worker_id IS NOT NULL)
		ORDER BY decline_count ASC, (SELECT COUNT(*) FROM assignments WHERE worker_id=users.user_id AND status IN ('pending','accepted','in_progress')) ASC
		LIMIT 1
	`, role, id)
	if err != nil {
		return
	}
	defer rows.Close()
	for rows.Next() {
		var w uuid.UUID
		if err := rows.Scan(&w); err == nil {
			_, _ = globalState.PG.Exec(castCtx(ctx), `UPDATE assignments SET worker_id=$2, status='pending' WHERE assignment_id=$1`, id, w)
			globalState.Realtime.Emit(castCtx(ctx), "assignment_offered", "assignment", id.String(), map[string]any{"workerId": w})
		}
	}
}

func castCtx(ctx interface{}) (out interface {
	Deadline() (time.Time, bool)
	Done() <-chan struct{}
	Err() error
	Value(any) any
}) {
	// We expect *gin.Context from the caller, but the helper takes interface{} for testability.
	type ctxIface interface {
		Deadline() (time.Time, bool)
		Done() <-chan struct{}
		Err() error
		Value(any) any
	}
	if v, ok := ctx.(ctxIface); ok {
		return v
	}
	// Last resort: pass nil; queries will fail and be ignored.
	return nil
}

var _ = pgx.ErrNoRows
var _ = errors.New"}

