	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "record_worker_location", "worker", sess.UserID.String(), true, map[string]any{
		"assignmentId": id.String(), "sequence": in.Sequence,
	})
	globalState.Realtime.Emit(c.Request.Context(), "worker_location", "worker", sess.UserID.String(), map[string]any{
		"latitude": in.Coordinate.Latitude, "longitude": in.Coordinate.Longitude, "recordedAt": recorded,
	})
	c.JSON(http.StatusOK, gin.H{"data": gin.H{
		"assignmentId": id,
		"sequence":     in.Sequence,
		"recordedAt":   recorded.Format(time.RFC3339Nano),
	}})
}

// reofferAssignment picks another qualified worker and re-offers the assignment.
func reofferAssignment(ctx context.Context, id uuid.UUID, a assignment) {
	role := assignmentRole(a)
	if role == "" {
		return
	}
	rows, err := globalState.PG.Query(ctx, `
		SELECT user_id FROM users
		WHERE active=TRUE AND available=TRUE AND $1 = ANY(roles)
		  AND decline_count < 5
		  AND (worker_id IS NULL OR worker_id <> (SELECT worker_id FROM assignments WHERE assignment_id=$2))
		ORDER BY decline_count ASC, (SELECT COUNT(*) FROM assignments WHERE worker_id=users.user_id AND status IN ('pending','accepted','in_progress')) ASC
		LIMIT 1
	`, role, id)
	if err != nil {
		return
	}
	defer rows.Close()
	for rows.Next() {
		var w uuid.UUID
		if err := rows.Scan(&w); err == nil {
			_, _ = globalState.PG.Exec(ctx, `UPDATE assignments SET worker_id=$2, status='pending' WHERE assignment_id=$1`, id, w)
			globalState.Realtime.Emit(ctx, "assignment_offered", "assignment", id.String(), map[string]any{"workerId": w})
		}
	}
}

func assignmentRole(a assignment) string {
	switch a.Kind {
	case "collection":
		return "collection_professional"
	case "transport":
		return "delivery_partner"
	case "node":
		return "node_handler"
	case "laboratory":
		return "laboratory_team"
	}
	return ""
}

var _ = pgx.ErrNoRows
var _ = errors.New"}

