{"security_risk":"LOW","summary":"Create read handlers","command":"create","path":"/workspace/backend/internal/api/handlers_read.go","file_text":"package api

import (
	"context"
	"errors"
	"net/http"
	"time"

	"github.com/gin-gonic/gin"
	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
)

// opsFilters is the input shape for /api/read-operations-state.
type opsFilters struct {
	SampleTypeID *uuid.UUID
}

func buildOperationsState(ctx context.Context, filters *opsFilters) (gin.H, APIError) {
	if filters == nil {
		filters = &opsFilters{}
	}
	// Samples
	samples := []gin.H{}
	rows, err := globalState.PG.Query(ctx, `
		SELECT s.sample_id, s.request_id, s.status, s.current_holder_id, s.active_journey_id, s.delivery_deadline,
		       s.location_latitude, s.location_longitude, s.location_recorded_at
		FROM samples s
		WHERE ($1::uuid IS NULL OR s.sample_type_id=$1)
		ORDER BY s.requested_at DESC LIMIT 500
	`, filters.SampleTypeID)
	if err != nil {
		return nil, Err(http.StatusInternalServerError, "internal_error", err.Error())
	}
	defer rows.Close()
	for rows.Next() {
		var (
			id, requestID, status                  string
			holder, journey                        *uuid.UUID
			deadline                               time.Time
			lat, lon                               *float64
			recorded                               *time.Time
		)
		if err := rows.Scan(&id, &requestID, &status, &holder, &journey, &deadline, &lat, &lon, &recorded); err == nil {
			s := gin.H{
				"sampleId": id, "status": status, "requestId": requestID,
				"deliveryDeadline": deadline.Format(time.RFC3339Nano),
				"locationStale":    isStale(recorded),
			}
			if holder != nil {
				s["currentHolderId"] = holder
			}
			if journey != nil {
				s["activeJourneyId"] = journey
			}
			if lat != nil && lon != nil {
				s["latestLocation"] = gin.H{"latitude": *lat, "longitude": *lon}
			}
			if recorded != nil {
				s["locationRecordedAt"] = recorded.Format(time.RFC3339Nano)
			}
			samples = append(samples, s)
		}
	}
	// Workers
	workers := []gin.H{}
	rows2, err := globalState.PG.Query(ctx, `
		SELECT user_id, COALESCE(full_name,''), roles, available, capacity_units, decline_count
		FROM users WHERE active=TRUE AND 'collection_professional' = ANY(roles) OR 'delivery_partner' = ANY(roles) OR 'node_handler' = ANY(roles) OR 'laboratory_team' = ANY(roles)
	`)
	if err != nil {
		return nil, Err(http.StatusInternalServerError, "internal_error", err.Error())
	}
	defer rows2.Close()
	for rows2.Next() {
		var id uuid.UUID
		var name string
		var roles []string
		var available bool
		var units, declines int
		if err := rows2.Scan(&id, &name, &roles, &available, &units, &declines); err == nil {
			// Get latest location from worker_locations.
			var lat, lon *float64
			var recorded *time.Time
			row := globalState.PG.QueryRow(ctx, `SELECT latitude, longitude, recorded_at FROM worker_locations WHERE worker_id=$1 ORDER BY recorded_at DESC LIMIT 1`, id)
			_ = row.Scan(&lat, &lon, &recorded)
			var count int
			_ = globalState.PG.QueryRow(ctx, `SELECT COUNT(*) FROM assignments WHERE worker_id=$1 AND status IN ('pending','accepted','in_progress')`, id).Scan(&count)
			w := gin.H{
				"workerId":       id,
				"fullName":       name,
				"roles":          roles,
				"available":      available,
				"status":         "available",
				"capacityUnits":  units,
				"assignmentCount": count,
				"locationStale":  isStale(recorded),
			}
			if !available {
				w["status"] = "unavailable"
			}
			if recorded != nil {
				w["locationRecordedAt"] = recorded.Format(time.RFC3339Nano)
			}
			if lat != nil && lon != nil {
				w["latestLocation"] = gin.H{"latitude": *lat, "longitude": *lon}
			}
			workers = append(workers, w)
		}
	}
	// Locations
	locations := []gin.H{}
	rows3, err := globalState.PG.Query(ctx, `
		SELECT location_id, name, latitude, longitude, active, coverage_km, handling_minutes, functions, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
		FROM locations ORDER BY name
	`)
	if err != nil {
		return nil, Err(http.StatusInternalServerError, "internal_error", err.Error())
	}
	defer rows3.Close()
	for rows3.Next() {
		var (
			id                                                                       uuid.UUID
			name                                                                     string
			lat, lon                                                                 float64
			active                                                                   bool
			cov                                                                      float64
			handling                                                                 int
			fns, sampleTypes                                                         []string
			fnsRaw                                                                   []byte
			capUnits, resUnits, cooledCap, cooledRes                                 int
		)
		_ = sampleTypes
		if err := rows3.Scan(&id, &name, &lat, &lon, &active, &cov, &handling, &fnsRaw, &capUnits, &resUnits, &cooledCap, &cooledRes); err == nil {
			// accepted sample types
			row := globalState.PG.QueryRow(ctx, `SELECT COALESCE(array_agg(sample_type_id::text), '{}') FROM laboratory_acceptance WHERE location_id=$1 AND accepts=TRUE`, id)
			_ = row.Scan(&sampleTypes)
			var fmap map[string]bool
			decodeJSON(fnsRaw, &fmap)
			locations = append(locations, gin.H{
				"id": id, "locationId": id, "name": name,
				"coordinate":     gin.H{"latitude": lat, "longitude": lon},
				"active":         active,
				"coverageKm":     cov,
				"handlingMinutes": handling,
				"functions":      locationFunctions(fmap),
				"capacity": gin.H{
					"capacityUnits":            capUnits,
					"reservedUnits":            resUnits,
					"availableUnits":           capUnits - resUnits,
					"cooledCapacityUnits":      cooledCap,
					"cooledReservedUnits":      cooledRes,
					"cooledAvailableUnits":     cooledCap - cooledRes,
				},
				"acceptedSampleTypeIds": sampleTypes,
			})
		}
	}
	// Connections
	conns := []gin.H{}
	rows4, err := globalState.PG.Query(ctx, `
		SELECT connection_id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
		FROM connections
	`)
	if err != nil {
		return nil, Err(http.StatusInternalServerError, "internal_error", err.Error())
	}
	defer rows4.Close()
	for rows4.Next() {
		var (
			id, from, to                                                              uuid.UUID
			travel                                                                    int
			cost                                                                      float64
			cooled, active                                                            bool
			capUnits, resUnits, cooledCap, cooledRes                                  int
		)
		if err := rows4.Scan(&id, &from, &to, &travel, &cost, &cooled, &active, &capUnits, &resUnits, &cooledCap, &cooledRes); err == nil {
			conns = append(conns, gin.H{
				"id": id, "connectionId": id,
				"fromLocationId": from, "toLocationId": to,
				"travelMinutes": travel, "costUnits": cost, "cooled": cooled, "active": active,
				"capacity": gin.H{
					"capacityUnits":         capUnits,
					"reservedUnits":         resUnits,
					"availableUnits":        capUnits - resUnits,
					"cooledCapacityUnits":   cooledCap,
					"cooledReservedUnits":   cooledRes,
					"cooledAvailableUnits":  cooledCap - cooledRes,
				},
			})
		}
	}
	// Spread
	var spread int
	row := globalState.PG.QueryRow(ctx, `
		SELECT COALESCE(MAX(c) - MIN(c), 0) FROM (
		  SELECT COUNT(*) c FROM assignments WHERE status IN ('accepted','in_progress') GROUP BY worker_id
		) s
	`)
	_ = row.Scan(&spread)
	var ineligible int
	_ = globalState.PG.QueryRow(ctx, `SELECT COUNT(*) FROM assignments WHERE status='ineligible'`, ).Scan(&ineligible)
	state := gin.H{
		"samples":                  samples,
		"workers":                  workers,
		"locations":                locations,
		"connections":              conns,
		"routes":                   []any{},
		"handoffs":                 []any{},
		"delays":                   []any{},
		"exceptions":               []any{},
		"assignmentCountSpread":    spread,
		"ineligibleAssignmentCount": ineligible,
	}
	return state, APIError{}
}

// handleReadOperationsState returns the dispatcher dashboard data.
func handleReadOperationsState(c *gin.Context) {
	sess := currentSession(c)
	if sess.ActiveRole != "administrator" && sess.ActiveRole != "dispatcher" {
		WriteError(c, Err(http.StatusForbidden, "role_not_held", "dispatcher/admin only"))
		return
	}
	var in struct {
		Filters struct {
			SampleTypeID string `json:"sampleTypeId"`
		} `json:"filters"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	f := opsFilters{}
	if in.Filters.SampleTypeID != "" {
		id, err := uuid.Parse(in.Filters.SampleTypeID)
		if err != nil {
			WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid sampleTypeId"))
			return
		}
		f.SampleTypeID = &id
	}
	state, apierr := buildOperationsState(c.Request.Context(), &f)
	if apierr.HTTPStatus != 0 {
		WriteError(c, apierr)
		return
	}
	c.JSON(http.StatusOK, gin.H{"data": state})
}

// handleListRoleWork returns pending/in-progress/completed items for a role.
func handleListRoleWork(c *gin.Context) {
	sess := currentSession(c)
	var in struct {
		Role   string `json:"role"`
		Status string `json:"status"`
	}
	if err := ReadBody(c, &in); err != nil {
		WriteError(c, err.(APIError))
		return
	}
	role := in.Role
	if role == "" {
		role = sess.ActiveRole
	}
	roleKind := roleKindFromRole(role)
	stateFilter := in.Status
	pending := []gin.H{}
	inProgress := []gin.H{}
	completed := []gin.H{}
	// assignments
	if roleKind != "" {
		rows, err := globalState.PG.Query(c.Request.Context(), `
			SELECT assignment_id, journey_id, kind, worker_id, from_location_id, to_location_id, sequence, status, node_id, laboratory_id, sample_id, requires_cooled
			FROM assignments WHERE kind=$1 ORDER BY sequence ASC
		`, roleKind)
		if err == nil {
			for rows.Next() {
				var (
					id, kind, status                                                              string
					jid, from, to, nodeID, labID, sampleID                                        *uuid.UUID
					seq                                                                           int
					workerID                                                                      *uuid.UUID
					cooled                                                                        bool
				)
				if err := rows.Scan(&id, &jid, &kind, &workerID, &from, &to, &seq, &status, &nodeID, &labID, &sampleID, &cooled); err == nil {
					item := gin.H{
						"kind":         kind,
						"assignmentId": id,
						"sampleId":     sampleID,
						"status":       status,
						"history":      loadTimeline(c.Request.Context(), "assignment", id),
					}
					if jid != nil {
						item["journeyId"] = jid
					}
					if from != nil {
						item["fromLocationId"] = from
					}
					if to != nil {
						item["toLocationId"] = to
					}
					if sampleID != nil {
						item["sampleId"] = sampleID
					}
					item["sequence"] = seq
					if workerID == nil || *workerID == sess.UserID {
						if status == "pending" {
							if stateFilter == "" || stateFilter == "pending" {
								pending = append(pending, item)
							}
						} else if status == "accepted" || status == "in_progress" {
							if stateFilter == "" || stateFilter == "in_progress" {
								inProgress = append(inProgress, item)
							}
						} else if status == "completed" || status == "delivered" || status == "received" {
							if stateFilter == "" || stateFilter == "completed" {
								completed = append(completed, item)
							}
						}
					}
				}
			}
			rows.Close()
		}
	}
	// journeys and samples are surfaced for requesters/dispatchers.
	if role == "requester" {
		// samples owned by the user
		rows, _ := globalState.PG.Query(c.Request.Context(), `
			SELECT sample_id, request_id, status, requested_at, delivery_deadline, active_journey_id, current_holder_id, location_recorded_at
			FROM samples WHERE requester_id=$1 ORDER BY requested_at DESC LIMIT 200
		`, sess.UserID)
		if rows != nil {
			for rows.Next() {
				var (
					id, rid, status                                                                          string
					requested, deadline                                                                      time.Time
					journey, holder                                                                          *uuid.UUID
					recorded                                                                                 *time.Time
				)
				if err := rows.Scan(&id, &rid, &status, &requested, &deadline, &journey, &holder, &recorded); err == nil {
					item := gin.H{
						"kind": "sample", "sampleId": id, "requestId": rid, "status": status,
						"requestedAt": requested.Format(time.RFC3339Nano),
						"deliveryDeadline": deadline.Format(time.RFC3339Nano),
						"locationStale":  isStale(recorded),
						"history":        loadTimeline(c.Request.Context(), "sample", id),
					}
					if journey != nil {
						item["journeyId"] = journey
					}
					if holder != nil {
						item["currentHolderId"] = holder
					}
					if status == "received" || status == "completed" {
						completed = append(completed, item)
					} else {
						inProgress = append(inProgress, item)
					}
				}
			}
			rows.Close()
		}
	}
	if role == "dispatcher" || role == "administrator" {
		// show recent journeys
		rows, _ := globalState.PG.Query(c.Request.Context(), `
			SELECT j.journey_id, j.status, j.route_mode, j.plan_version, j.estimated_delivery_at,
			       COALESCE(ARRAY(SELECT sample_id FROM samples WHERE active_journey_id=j.journey_id), '{}'),
			       (SELECT COUNT(*) FROM assignments WHERE journey_id=j.journey_id)
			FROM journeys j ORDER BY j.created_at DESC LIMIT 200
		`)
		if rows != nil {
			for rows.Next() {
				var (
					id, status, mode                                                                  string
					plan                                                                              int
					eta                                                                               time.Time
					samples                                                                            []string
					count                                                                              int
				)
				if err := rows.Scan(&id, &status, &mode, &plan, &eta, &samples, &count); err == nil {
					item := gin.H{
						"kind": "journey", "journeyId": id, "status": status, "routeMode": mode,
						"planVersion": plan,
						"sampleIds":   samples,
						"estimatedDeliveryAt": eta.Format(time.RFC3339Nano),
						"assignmentCount":    count,
						"history": loadTimeline(c.Request.Context(), "journey", id),
					}
					if status == "completed" {
						completed = append(completed, item)
					} else {
						inProgress = append(inProgress, item)
					}
				}
			}
			rows.Close()
		}
	}
	c.JSON(http.StatusOK, gin.H{"data": gin.H{
		"pending":    pending,
		"inProgress": inProgress,
		"completed":  completed,
	}})
}

func roleKindFromRole(role string) string {
	switch role {
	case "collection_professional":
		return "collection"
	case "delivery_partner":
		return "transport"
	case "node_handler":
		return "node"
	case "laboratory_team":
		return "laboratory"
	}
	return ""
}

func loadTimeline(ctx context.Context, entityType, entityID string) []gin.H {
	if globalState.Audit == nil {
		return nil
	}
	entries, _ := globalState.Audit.Search(ctx, map[string]any{"entityType": entityType, "entityId": entityID, "limit": 200, "order": "newest_first"})
	out := make([]gin.H, 0, len(entries))
	for _, e := range entries {
		out = append(out, gin.H{
			"eventId":    e.EventID,
			"action":     e.Action,
			"actorId":    ptrString(e.ActorID),
			"role":       e.Role,
			"entityType": e.EntityType,
			"entityId":   e.EntityID,
			"success":    e.Success,
			"occurredAt": e.OccurredAt.Format(time.RFC3339Nano),
			"details":    e.Details,
		})
	}
	return out
}

