		return
	}
	if in.IdempotencyKey != "" {
		if existing, ok := idempotencyLookup(c.Request.Context(), in.IdempotencyKey); ok {
			c.JSON(http.StatusOK, existing)
			return
		}
	}
	target, err := uuid.Parse(in.TargetJourneyID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid targetJourneyId"))
		return
	}
	var currentVersion int
	if err := globalState.PG.QueryRow(c.Request.Context(), `SELECT plan_version FROM journeys WHERE journey_id=$1`, target).Scan(&currentVersion); err != nil {
		WriteError(c, Err(http.StatusNotFound, "not_found", "journey not found"))
		return
	}
	if currentVersion != in.ExpectedPlanVersion {
		WriteError(c, Err(http.StatusConflict, "state_snapshot_changed", "plan version mismatch"))
		return
	}
	for _, sid := range in.SourceJourneyIDs {
		src, err := uuid.Parse(sid)
		if err != nil {
			WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid sourceJourneyId"))
			return
		}
		_, err = globalState.PG.Exec(c.Request.Context(), `
