		`, src, target)
		if err != nil {
			WriteError(c, Err(http.StatusInternalServerError, "internal_error", err.Error()))
			return
		}
		_, _ = globalState.PG.Exec(c.Request.Context(), `UPDATE journeys SET status='merged' WHERE journey_id=$1`, src)
	}
	_, _ = globalState.PG.Exec(c.Request.Context(), `UPDATE journeys SET plan_version=plan_version+1, updated_at=NOW() WHERE journey_id=$1`, target)
	auditWrite(c.Request.Context(), &sess.UserID, sess.ActiveRole, "merge_journeys", "journey", target.String(), true, nil)
	resp := gin.H{"targetJourneyId": target, "mergedCount": len(in.SourceJourneyIDs)}
	if in.IdempotencyKey != "" {
		idempotencyStore(c.Request.Context(), in.IdempotencyKey, resp)
	}
	c.JSON(http.StatusOK, gin.H{"data": resp})
}

