		}
	}
	id, err := uuid.Parse(in.JourneyID)
	if err != nil {
		WriteError(c, Err(http.StatusBadRequest, "invalid_json", "invalid journeyId"))
		return
	}
	var currentVersion int
	if err := globalState.PG.QueryRow(c.Request.Context(), `SELECT plan_version FROM journeys WHERE journey_id=$1`, id).Scan(&currentVersion); err != nil {
