	ActorID    *uuid.UUID     `json:"actorId"`
	Role       string         `json:"role"`
	Action     string         `json:"action"`
	EntityType string         `json:"entityType"`
	EntityID   string         `json:"entityId"`
	Success    bool           `json:"success"`
	OccurredAt time.Time      `json:"occurredAt"`
	Details    map[string]any `json:"details"`
}

func (l *Logger) Search(ctx context.Context, q map[string]any) ([]EntryView, error) {
	entityType, _ := q["entityType"].(string)
	entityID, _ := q["entityId"].(string)
	limit := 200
	if v, ok := q["limit"].(int); ok && v > 0 && v <= 1000 {
		limit = v
	}
	rows, err := l.pool.Query(ctx, `
		SELECT event_id, actor_id, COALESCE(role,''), action, entity_type, COALESCE(entity_id,''), success, occurred_at, details
		FROM audit_trail
		WHERE ($1 = '' OR entity_type = $1)
		  AND ($2 = '' OR entity_id = $2)
		ORDER BY occurred_at DESC
		LIMIT $3
	`, entityType, entityID, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := make([]EntryView, 0, 32)
	for rows.Next() {
		var (
			ev      EntryView
			details []byte
		)
		if err := rows.Scan(&ev.EventID, &ev.ActorID, &ev.Role, &ev.Action, &ev.EntityType, &ev.EntityID, &ev.Success, &ev.OccurredAt, &details); err != nil {
			return nil, err
		}
		if len(details) > 0 {
			_ = json.Unmarshal(details, &ev.Details)
		}
		out = append(out, ev)
	}
	return out, rows.Err()
}

type SearchPagedResult struct {
	Entries []EntryView `json:"entries"`
	Total   int         `json:"total"`
}

func (l *Logger) SearchPaged(ctx context.Context, q map[string]any) (SearchPagedResult, error) {
	entityType, _ := q["entityType"].(string)
	entityID, _ := q["entityId"].(string)
	actor, _ := q["actorId"].(string)
	role, _ := q["role"].(string)
	action, _ := q["action"].(string)
	limit := 100
	if v, ok := q["limit"].(int); ok && v > 0 && v <= 500 {
		limit = v
	}
	offset := 0
	if v, ok := q["offset"].(int); ok && v >= 0 {
		offset = v
	}
	rows, err := l.pool.Query(ctx, `
		SELECT event_id, actor_id, COALESCE(role,''), action, entity_type, COALESCE(entity_id,''), success, occurred_at, details
		FROM audit_trail
		WHERE ($1 = '' OR entity_type = $1)
		  AND ($2 = '' OR entity_id = $2)
		  AND ($3 = '' OR actor_id::text = $3)
		  AND ($4 = '' OR role = $4)
		  AND ($5 = '' OR action = $5)
		ORDER BY occurred_at DESC
		LIMIT $6 OFFSET $7
	`, entityType, entityID, actor, role, action, limit, offset)
	if err != nil {
		return SearchPagedResult{}, err
	}
	defer rows.Close()
	out := SearchPagedResult{Entries: make([]EntryView, 0, limit)}
	for rows.Next() {
		var (
			ev      EntryView
			details []byte
		)
		if err := rows.Scan(&ev.EventID, &ev.ActorID, &ev.Role, &ev.Action, &ev.EntityType, &ev.EntityID, &ev.Success, &ev.OccurredAt, &details); err != nil {
			return out, err
		}
		if len(details) > 0 {
			_ = json.Unmarshal(details, &ev.Details)
		}
		out.Entries = append(out.Entries, ev)
	}
	if err := l.pool.QueryRow(ctx, `
		SELECT COUNT(*) FROM audit_trail
		WHERE ($1 = '' OR entity_type = $1)
		  AND ($2 = '' OR entity_id = $2)
		  AND ($3 = '' OR actor_id::text = $3)
		  AND ($4 = '' OR role = $4)
		  AND ($5 = '' OR action = $5)
	`, entityType, entityID, actor, role, action).Scan(&out.Total); err != nil {
		return out, err
	}
	return out, rows.Err()
}"}

