{"security_risk":"LOW","summary":"Add realtime Recent/Cursor","command":"str_replace","path":"/workspace/backend/internal/realtime/hub.go","old_str":"// NewEventID returns a unique id (uuid) helper for payloads.
func NewEventID() string { return uuid.NewString() }","new_str":"// NewEventID returns a unique id (uuid) helper for payloads.
func NewEventID() string { return uuid.NewString() }

// Recent returns the most recent persisted events after `since`. If `since` is
// zero, returns the most recent `limit` events. It reads from realtime_events
// when a pool is attached, otherwise returns nil.
func (h *Hub) Recent(since time.Time, limit int) []Event {
	if h.pool == nil || limit <= 0 {
		return nil
	}
	rows, err := h.pool.Query(context.Background(), `
		SELECT id, event_type, COALESCE(entity_type,''), COALESCE(entity_id,''), payload, created_at
		FROM realtime_events
		WHERE ($1::timestamptz IS NULL OR created_at > $1)
		ORDER BY id DESC
		LIMIT $2
	`, nullableTime(since), limit)
	if err != nil {
		log.Printf("realtime recent: %v", err)
		return nil
	}
	defer rows.Close()
	out := make([]Event, 0, limit)
	for rows.Next() {
		var e Event
		var payload []byte
		if err := rows.Scan(&e.ID, &e.Type, &e.EntityType, &e.EntityID, &payload, &e.CreatedAt); err != nil {
			log.Printf("realtime recent scan: %v", err)
			continue
		}
		if len(payload) > 0 {
			_ = json.Unmarshal(payload, &e.Payload)
		}
		out = append(out, e)
	}
	return out
}

// Cursor returns the latest known event id (used for live-tailing).
func (h *Hub) Cursor() string {
	if h.pool == nil {
		return ""
	}
	var id int64
	if err := h.pool.QueryRow(context.Background(), `SELECT COALESCE(MAX(id),0) FROM realtime_events`).Scan(&id); err != nil {
		return ""
	}
	return strconv.FormatInt(id, 10)
}

func nullableTime(t time.Time) interface{} {
	if t.IsZero() {
		return nil
	}
	return t
}"}

