{"security_risk":"LOW","summary":"redis helpers","command":"create","path":"/workspace/backend/internal/store/redis_helpers.go","file_text":"package store

import (
	"context"

	"github.com/redis/go-redis/v9"
)

// CleanRedisForReset removes application-owned Redis keys so the runtime
// starts from a known-empty cache. Errors are swallowed because reset
// tolerates partial failures and the schema in Postgres is the source of
// truth.
func CleanRedisForReset(ctx context.Context, rds *redis.Client) error {
	if rds == nil {
		return nil
	}
	patterns := []string{
		"serviceability:*",
		"svc:version",
		"realtime:*",
		"presence:*",
		"offers:*",
	}
	for _, p := range patterns {
		iter := rds.Scan(ctx, 0, p, 200).Iterator()
		keys := make([]string, 0, 64)
		for iter.Next(ctx) {
			keys = append(keys, iter.Val())
			if len(keys) >= 200 {
				_ = rds.Del(ctx, keys...).Err()
				keys = keys[:0]
			}
		}
		if len(keys) > 0 {
			_ = rds.Del(ctx, keys...).Err()
		}
		if err := iter.Err(); err != nil {
			return err
		}
	}
	return nil
}"}
